type DrawerRootChangeEventDetails = ({
    reason: 'trigger-press';
    event: KeyboardEvent | MouseEvent | TouchEvent | PointerEvent;
} | {
    reason: 'outside-press';
    event: MouseEvent | TouchEvent | PointerEvent;
} | {
    reason: 'escape-key';
    event: KeyboardEvent;
} | {
    reason: 'close-press';
    event: KeyboardEvent | MouseEvent | PointerEvent;
} | {
    reason: 'focus-out';
    event: FocusEvent | KeyboardEvent;
} | {
    reason: 'imperative-action';
    event: Event;
} | {
    reason: 'none';
    event: Event;
} | {
    reason: 'close-watcher';
    event: Event;
} | {
    reason: 'swipe';
    event: TouchEvent | PointerEvent;
}) & {
    cancel: () => void;
    allowPropagation: () => void;
    isCanceled: boolean;
    isPropagationAllowed: boolean;
    trigger: Element | undefined;
    preventUnmountOnClose: () => void;
};

